<!-- admin/gestion-pages.php --> <?php session_start(); include('../database/config.php'); if(!isset($_SESSION['role']) || $_SESSION['role']!='admin'){ header("Location: ../login.php"); exit(); } $pages=['index.php','services.php','infos.html','formation.html','demande-stage.php']; if(isset($_POST['sauvegarder'])){ $page=$_POST['page']; $contenu=$_POST['contenu']; file_put_contents("../".$page,$contenu); } ?> <!DOCTYPE html> <html lang="fr"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Gestion des Pages</title> <link rel="stylesheet" href="../assets/css/dashboard.css"> </head> <body> <header><h2>Gestion des Pages du Site</h2></header> <section class="dashboard"> <div class="card" style="width:100%;max-width:800px;"> <h3>Modifier une page</h3> <form method="post"> <select name="page"> <?php foreach($pages as $p){echo "<option value='$p'>$p</option>";} ?> </select> <textarea name="contenu" rows="15" style="width:100%;" placeholder="Contenu HTML de la page"></textarea> <button type="submit" name="sauvegarder">Sauvegarder</button> </form> </div> </section> </body> </html>